      {
        "type": "paragraph",
        "snippet": "You can apply for a new ration card online through the National Food Security Portal or via your respective State/UT Government’s official food and civil supplies website.",
        "snippet_links": [
          {
            "text": "National Food Security Portal",
            "link": "https://nfsa.gov.in/portal/apply"
          }
        ],
        "snippet_highlighted_words": [
          "through the National Food Security Portal or via your respective State/UT Government’s official food and civil supplies website"
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "heading",
        "snippet": "General Steps to Apply Online"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Visit the Portal: Go to the NFSA Official Portal and select your State or Union Territory to be redirected to the local food portal (such as MahaFood in Maharashtra or Odisha's PDS Odisha).",
            "snippet_links": [
              {
                "text": "MahaFood",
                "link": "https://mahafood.gov.in/en/services/"
              },
              {
                "text": "PDS Odisha",
                "link": "https://pdsodisha.gov.in/NFSA/CitizenshipEnrollmentNew/CitizenshipEnrollmentNew"
              }
            ],
            "reference_indexes": [
              0,
              1,
              2
            ]
          },
          {
            "snippet": "Register / Login: Create a new user profile or log in using your Aadhaar or registered mobile number."
          },
          {
            "snippet": "Fill the Application Form: Enter head-of-family details, residential address, income details, and particulars of all family members.",
            "reference_indexes": [
              1,
              3
            ]
          },
          {
            "snippet": "Upload Documents: Attach required scanned copies, which typically include:",
            "list": [
              {
                "snippet": "Aadhaar cards of family members"
              },
              {
                "snippet": "Proof of residence (Electricity bill, water bill, or rent agreement)"
              },
              {
                "snippet": "Passport-size photograph of the family head"
              },
              {
                "snippet": "LPG/Gas connection details (if applicable)"
              },
              {
                "snippet": "Surrender certificate or deletion certificate if moving from another ration card/jurisdiction"
              }
            ],
            "reference_indexes": [
              3,
              4,
              5
            ]
          },
          {
            "snippet": "Submit and Track: Submit the form and note down the application reference number to track its status online.",
            "reference_indexes": [
              4,
              6
            ]
          }
        ]
      },
      {
        "type": "paragraph",
        "snippet": "Which State or Union Territory are you applying from? Let me know so I can share the exact direct link and required documents for your region."
      }
    ],
